import{hydrateWorkflowDemo,validateDemo}from'./mopix-workflow-demo.js';
import{sanitizeGraph}from'./mopix-node-graph.js';
// Validation never sorts edges: their order defines @image1…@image5.
export function prepareWorkflowTemplate(template){
 if(!template?.id||!Array.isArray(template.nodes)||!Array.isArray(template.edges))throw Error('Workflow thiếu dữ liệu node hoặc đường nối.');
 validateDemo(template);
 for(const n of template.nodes){if(typeof n.title!=='string'||n.title.length>80||typeof n.prompt!=='string'||n.prompt.length>20000||!['16:9','9:16','1:1'].includes(n.ratio)||![5,10].includes(n.duration)||Math.abs(n.x)>100000||Math.abs(n.y)>100000)throw Error('Thiết lập không hợp lệ ở node '+(n.title||n.id));}
 let graph;try{graph=sanitizeGraph({version:1,nodes:template.nodes,edges:template.edges})}catch(e){throw Error('Workflow không hợp lệ: '+e.message)}
 graph.template={id:template.id,name:String(template.name_vi||'').slice(0,200),instructions:String(template.how_to_use_vi||'').replace(/Bấm 'Chạy quy trình' trên node Video cuối để chạy cả chuỗi\./g,"Dùng 'Chạy toàn bộ Canvas' để chạy mọi nhánh.").slice(0,5000)};return graph;
}
export function createWorkflowTemplates(React){const{createElement:h,useState:S,useEffect:E,useRef:R}=React;return function WorkflowTemplates({onLoad,onClose}){
 const[rows,ROWS]=S([]),[error,ERR]=S(''),[loading,LOADING]=S(false),modal=R(null),lock=R(false);E(()=>{modal.current.showModal();const controller=new AbortController();fetch('/assets/data/workflow-templates.json',{signal:controller.signal}).then(async r=>{if(!r.ok)throw Error('Không tải được workflow mẫu.');const d=await r.json();if(d.version!==1||!Array.isArray(d.templates))throw Error('Định dạng kho workflow không hợp lệ.');ROWS(d.templates)}).catch(e=>{if(e.name!=='AbortError')ERR(e.message)});return()=>controller.abort()},[]);
 return h('dialog',{ref:modal,className:'mopix-options-modal mopix-workflow-templates','aria-label':'Workflow mẫu',onCancel:e=>{if(lock.current)e.preventDefault();else onClose()}},h('section',null,h('header',null,h('h2',null,'Workflow mẫu'),h('button',{type:'button',onClick:onClose,disabled:loading,'aria-label':'Đóng workflow mẫu'},'Đóng')),h('p',null,'Chọn quy trình để bắt đầu. Demo có ảnh sẵn sẽ tự nhập ảnh vào thư viện; các mẫu khác cần ảnh của bạn. Canvas hiện tại luôn được sao lưu trước khi thay.'),error&&h('p',{role:'alert'},error),!rows.length&&!error&&h('p',{role:'status'},'Đang tải…'),h('div',{className:'mopix-workflow-template-list'},...rows.map(t=>h('article',{key:t.id},h('small',null,t.category+' · '+t.nodes.length+' node · '+t.edges.length+' đường nối'+(t.demo?' · Có ảnh demo':'')),h('h3',null,t.name_vi),h('p',null,t.description),h('p',{className:'mopix-workflow-instructions'},t.how_to_use_vi.replace(/Bấm 'Chạy quy trình' trên node Video cuối để chạy cả chuỗi\./g,"Dùng 'Chạy toàn bộ Canvas' để chạy mọi nhánh.")),h('button',{type:'button',disabled:loading,onClick:async()=>{if(lock.current)return;try{const prepared=prepareWorkflowTemplate(t);if(!window.confirm('Thay canvas hiện tại bằng template “'+t.name_vi+'”? Bản nháp cũ sẽ được sao lưu.'))return;lock.current=true;LOADING(true);ERR('');const graph=await hydrateWorkflowDemo(t,prepared);onLoad(graph);onClose()}catch(e){ERR(e.message)}finally{lock.current=false;LOADING(false)}}},loading?'Đang nhập demo…':'Nạp workflow'))))));
}}
